#[test]
fn authenticated_request_rejects_replay_and_tampering() {
    let work = tempfile::tempdir().unwrap();
    let key_path = work.path().join("peer.key");
    let auth = generate_key(&key_path).unwrap();
    let store = ObjectStore::open(work.path().join("receiver"));
    let request = authenticated_request(&auth, b"canonical payload");
    auth.verify_request(&store, &request, "controller.node", "worker.node")
        .unwrap();
    let replay = auth
        .verify_request(&store, &request, "controller.node", "worker.node")
        .unwrap_err();
    assert!(format!("{replay:#}").contains("replayed"));

    let mut tampered = authenticated_request(&auth, b"original");
    tampered.body = b"tampered".to_vec();
    let rejected = auth
        .verify_request(
            &ObjectStore::open(work.path().join("tampered")),
            &tampered,
            "controller.node",
            "worker.node",
        )
        .unwrap_err();
    assert!(format!("{rejected:#}").contains("tag mismatch"));
}

